create extension if not exists pgcrypto;
create type public.user_role as enum ('patient','admin');
create type public.query_urgency as enum ('routine','review','urgent');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,role public.user_role not null default 'patient',created_at timestamptz not null default now());
create table public.healthcare_queries (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,text text not null check (char_length(text) between 5 and 1000),category text,confidence numeric check (confidence between 0 and 1),urgency public.query_urgency,destination text,explanation jsonb,model_version text,requires_human_review boolean not null default false,created_at timestamptz not null default now());
create table public.appointments (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,specialty text not null,provider_name text,status text not null default 'requested',scheduled_at timestamptz,created_at timestamptz not null default now());
create index healthcare_queries_user_created_idx on public.healthcare_queries(user_id,created_at desc);
create index appointments_user_scheduled_idx on public.appointments(user_id,scheduled_at);
alter table public.profiles enable row level security;alter table public.healthcare_queries enable row level security;alter table public.appointments enable row level security;
create policy "profile owner read" on public.profiles for select using (auth.uid()=id);
create policy "profile owner insert" on public.profiles for insert with check (auth.uid()=id);
create policy "profile owner update" on public.profiles for update using (auth.uid()=id);
create policy "query owner read" on public.healthcare_queries for select using (auth.uid()=user_id);
create policy "query owner insert" on public.healthcare_queries for insert with check (auth.uid()=user_id);
create policy "query owner update" on public.healthcare_queries for update using (auth.uid()=user_id);
create policy "appointment owner read" on public.appointments for select using (auth.uid()=user_id);
create policy "appointment owner insert" on public.appointments for insert with check (auth.uid()=user_id);
create policy "appointment owner update" on public.appointments for update using (auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email) values(new.id,new.email); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
